function buildRaionBordersGroup() {
    const isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    const color = isDark ? '#a8b1bd' : '#5e5238';
    const layer = L.layerGroup();

    Object.values(RAION_BORDERS).forEach((ring) => {
        L.polygon(ring, {
            pane: 'raionBordersPane',
            interactive: false,
            className: 'raion-border',
            color,
            fill: false,
            weight: 1,
            opacity: isDark ? 0.6 : 0.75,
        }).addTo(layer);
    });

    return layer;
}

export { buildRaionBordersGroup, RAION_BORDERS };
